package wgmodern;
import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.network.chat.Component;import net.minecraft.ChatFormatting;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.item.context.UseOnContext;import net.minecraft.world.level.Level;import tc4revival.aspect.*;import tc4revival.content.*;
public class ArcaneCalculator extends Item {
 public ArcaneCalculator(){super(new Properties().stacksTo(1));}@Override public String getDescriptionId(){return "item.WG_Material.calculator";}
 public record Warning(String kind,BlockPos pos){}public record Survey(int symmetry,List<BlockPos> pedestals,List<Warning> warnings){}
 public static AspectAmounts primals(AspectAmounts input){return TCAspects.catalog().toPrimals(input,AspectCatalog.Reduction.SUM);}
 public static Survey survey(Level level,BlockPos origin){var pedestals=new ArrayList<BlockPos>();var stabilizers=new ArrayList<BlockPos>();var warnings=new ArrayList<Warning>();for(int x=-12;x<=12;x++)for(int z=-12;z<=12;z++){boolean skip=false;for(int y=-10;y<=5;y++){if(x==0&&z==0)continue;var p=origin.offset(x,y,z);if(!level.hasChunkAt(p)||level.isOutsideBuildHeight(p))continue;if(!skip&&level.getBlockEntity(p) instanceof ArcanePedestalBlockEntity){if(y>=0)warnings.add(new Warning("pedestalHeight",p));else if(Math.abs(x)>8||Math.abs(z)>8)warnings.add(new Warning("pedestalPos",p));else{pedestals.add(p);skip=true;}}else if(stabilizes(level,p))stabilizers.add(p);}}
  int symmetry=0;for(var p:pedestals){var here=(ArcanePedestalBlockEntity)level.getBlockEntity(p);boolean occupied=!here.isEmpty();symmetry+=occupied?3:2;var opposite=mirror(origin,p);if(level.hasChunkAt(opposite)&&level.getBlockEntity(opposite) instanceof ArcanePedestalBlockEntity other){symmetry-=2;if(!other.isEmpty()){if(occupied)symmetry--;else warnings.add(new Warning("noPartnerItem",opposite));}}else warnings.add(new Warning("noPartnerPedestal",p));}
  float decorative=0;for(var p:stabilizers){decorative+=.1f;var opposite=mirror(origin,p);if(level.hasChunkAt(opposite)&&stabilizes(level,opposite))decorative-=.2f;else warnings.add(new Warning("noPartnerStabilizer",p));}return new Survey((int)(symmetry+decorative),List.copyOf(pedestals),List.copyOf(warnings));
 }
 private static BlockPos mirror(BlockPos o,BlockPos p){return new BlockPos(2*o.getX()-p.getX(),p.getY(),2*o.getZ()-p.getZ());}
 private static boolean stabilizes(Level l,BlockPos p){var s=l.getBlockState(p);if(s.getBlock() instanceof thaumcraft.api.crafting.IInfusionStabiliser b)return b.canStabiliseInfusion(l,p);if(l.getBlockEntity(p) instanceof thaumcraft.api.crafting.IInfusionStabiliser b)return b.canStabiliseInfusion(l,p);return s.is(InfusionLayout.STABILIZERS);}
 @Override public InteractionResult onItemUseFirst(ItemStack s,UseOnContext c){var l=c.getLevel();var be=l.getBlockEntity(c.getClickedPos());if(!(be instanceof ScannableNode)&&!(be instanceof InfusionMatrixBlockEntity))return InteractionResult.PASS;if(!(c.getPlayer() instanceof ServerPlayer p))return InteractionResult.SUCCESS;if(be instanceof ScannableNode n){var amounts=primals(n.aspects());Object[] count=List.of("aer","terra","ignis","aqua","ordo","perditio").stream().map(tag->amounts.amount(TCAspects.catalog().require(tag))).toArray();p.sendSystemMessage(Component.translatable("wg.chat.nodeContents.primal",count));return InteractionResult.CONSUME;}
  var origin=c.getClickedPos();var survey=survey(l,origin);p.sendSystemMessage(Component.translatable("wg.chat.infusionInfo.stabilityTotal",-survey.symmetry()).withStyle(ChatFormatting.DARK_PURPLE));if(l.getBlockEntity(origin.below(2)) instanceof ArcanePedestalBlockEntity center&&!center.isEmpty()){var components=InfusionLayout.scan(l,origin).pedestals().stream().map(l::getBlockEntity).filter(ArcanePedestalBlockEntity.class::isInstance).map(ArcanePedestalBlockEntity.class::cast).map(x->x.getItem(0)).filter(x->!x.isEmpty()).toList();var knowledge=tc4revival.research.KnowledgeSavedData.get(p.server).snapshot(p.getUUID());var input=new InfusionRecipe.Input(center.getItem(0),components,key->knowledge.map(k->k.researchMarkers().contains(key)).orElse(false),tc4revival.config.TCConfig.SERVER.orderedInfusion.get());InfusionRecipe.find(l,input).ifPresent(recipe->{var plan=recipe.plan(input);p.sendSystemMessage(Component.translatable("wg.chat.infusionInfo.instability",plan.instability()).withStyle(ChatFormatting.DARK_PURPLE));var definition=recipe.displayDefinition();if(plan.enchanting()){float modifier=net.minecraft.world.item.enchantment.EnchantmentHelper.getItemEnchantmentLevel(net.minecraftforge.registries.ForgeRegistries.ENCHANTMENTS.getValue(new net.minecraft.resources.ResourceLocation(definition.get("enchantment").getAsString())),center.getItem(0));for(var e:net.minecraft.world.item.enchantment.EnchantmentHelper.getEnchantments(center.getItem(0)).entrySet())if(!net.minecraftforge.registries.ForgeRegistries.ENCHANTMENTS.getKey(e.getKey()).toString().equals(definition.get("enchantment").getAsString()))modifier+=e.getValue()*.1f;if(tc4revival.config.TCConfig.SERVER.enhancedInfusionEnchanting.get())modifier=(float)components.stream().filter(stack->stack.is(net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(net.minecraft.resources.ResourceLocation.parse("thaumcraft:salis_mundus")))).count()-1;if(modifier>0){p.sendSystemMessage(Component.translatable("wg.chat.infusionInfo.essentiaMod",1+modifier).withStyle(ChatFormatting.GREEN));sendCosts(p,plan.aspects());}}else if(definition.has("mode")&&definition.get("mode").getAsString().equals("runic_augmentation")){p.sendSystemMessage(Component.translatable("wg.chat.infusionInfo.essentiaRunicMod",tc4revival.content.RunicGear.charge(center.getItem(0))).withStyle(ChatFormatting.GREEN));sendCosts(p,plan.aspects());}});}
  for(var w:survey.warnings())p.sendSystemMessage(Component.translatable("wg.chat.infusionWarning."+w.kind(),w.pos().getX(),w.pos().getY(),w.pos().getZ()).withStyle(ChatFormatting.DARK_GRAY));return InteractionResult.CONSUME;
 }
 private static void sendCosts(ServerPlayer p,AspectAmounts amounts){p.sendSystemMessage(Component.literal(String.join(", ",amounts.aspects().stream().map(a->amounts.amount(a)+" "+a.displayName()).toList())).withStyle(ChatFormatting.GRAY));}
}
